/// <summary>
///    Finds the specified record in the <c>KCS_KBVReqNumber</c> table.
/// </summary>
/// <param name="_recordId">
///    The record ID of the <c>KCS_KBVReqNumber</c> record to find.
/// </param>
/// <param name="_forUpdate">
///    A Boolean value that indicates whether to read the record for update; optional.
/// </param>
/// <returns>
///    A record in the <c>KCS_KBVReqNumber</c> table; otherwise, an empty record.
/// </returns>
public static KCS_KBVReqNumber find(    KCS_KBVBuildingProjectID    _recordId,
                                        boolean                     _forUpdate = false)
{
    KCS_KBVReqNumber record;

    if (_recordId)
    {
        record.selectForUpdate(_forUpdate);

        select firstonly record
        index hint BuildingProjectIDIdx
        where   record.BuildingProjectID == _recordId;
    }

    return record;
}

/// <summary>
///    Getss or set a specified id <c>KCS_KBVRequestId</c> based on <c>KCS_KBVBuildingProjectID</c>.
/// </summary>
/// <param name="_id">
///    The ID of the <c>KCS_KBVBuildingProjectID</c> to find.
/// </param>
/// <returns>
///    A id <c>KCS_KBVRequestId</c>.
/// </returns>
public static KCS_KBVRequestId getSetRequestNumber(KCS_KBVBuildingProjectID _id)
{
    KCS_KBVReqNumber        locKCS_KBVReqNumber;
    KCS_KBVRequestNumber    locKCS_KBVRequestNumber;
    KCS_KBVRequestId        retVal;

    locKCS_KBVRequestNumber = 0;

    if (_id)
    {
        locKCS_KBVReqNumber = KCS_KBVReqNumber::find(_id, true);

        if (locKCS_KBVReqNumber)
        {
            if (locKCS_KBVReqNumber.RequestNumber < 99)
            {
                ttsbegin;

                locKCS_KBVRequestNumber             = locKCS_KBVReqNumber.RequestNumber + 1;
                locKCS_KBVReqNumber.RequestNumber   = locKCS_KBVRequestNumber;
                locKCS_KBVReqNumber.update();

                ttscommit;
            }
            else
            {
                throw error("@NDX:NXAMoreThan99BPNotPossible");
            }
        }
        else
        {
            locKCS_KBVRequestNumber                 = 1;
            locKCS_KBVReqNumber.clear();
            locKCS_KBVReqNumber.BuildingProjectID   = _id;
            locKCS_KBVReqNumber.RequestNumber       = locKCS_KBVRequestNumber;
            locKCS_KBVReqNumber.insert();
        }
    }

    if (locKCS_KBVRequestNumber == 0)
    {
        throw error("@NDX:NXARequestNumberNotFound");
    }

    if (locKCS_KBVRequestNumber < 10)
    {
        retVal = '0';
    }

    retVal += int2str(locKCS_KBVRequestNumber);
    retVal = _id + retVal;

    return retVal;
}
